  "statement": "let input_txid = txn.inputs[i].prevTxId.toString("hex");",
  "change_type": "A",
  "function_name": "_isValidSlpTxid",
  "operation_type": "security_sensitive_decision",
  "selection_reason": "observable input/state -> exact operation -> security-sensitive effect",
  "security_relevance_score": 0.75,
  "code_context": "114:     // This method uses recursion to do a Depth-First-Search with the node result being
115:     // computed in Postorder Traversal (left/right/root) order.  A validation cache
116:     // is used to keep track of the results for nodes that have already been evaluated.
117:     //
118:     // Each call to this method evaluates node validity with respect to
119:     // its parent node(s), so it walks backwards until the
120:     // validation cache provides a result or the GENESIS node is evaluated.
121:     // Root nodes await the validation result of their upstream parent.
122:     //
123:     // In the case of NFT1 the search continues to the group/parent NFT DAG after the Genesis
124:     // of the NFT child is discovered.
125:     //
126:     async _isValidSlpTxid(txid: string, tokenIdFilter?: string, tokenTypeFilter?: number): Promise<boolean> {
127:         // Check to see if this txn has been processed by looking at shared cache, if doesn't exist then download txn.
128:         if (!this.cachedValidations[txid]) {
129:             this.cachedValidations[txid] = {
130:                 validity: null,
131:                 parents: [],
132:                 details: null,
133:                 invalidReason: null,
134:                 waiting: false,
135:             };
136:             await this.retrieveRawTransaction(txid);
137:         }
138:         // Otherwise, we can use the cached result as long as a special filter isn't being applied.
139:         else if (typeof this.cachedValidations[txid].validity === "boolean") {
140:             return this.cachedValidations[txid].validity!;
141:         }
142: 
143:         //
144:         // Handle the case where neither branch of the previous if/else statement was
145:         // executed and the raw transaction has never been downloaded.
146:         //
147:         // Also handle case where a 2nd request of same txid comes in
148:         // during the download of a previous request.
149:         //
150:         if (!this.cachedRawTransactions[txid] || this.cachedRawTransactions[txid] === "waiting") {
151:             if (this.cachedRawTransactions[txid] !== "waiting") {
152:                 this.retrieveRawTransaction(txid);
153:             }
154: 
155:             // Wait for previously a initiated download to completed
156:             await this.waitForTransactionDownloadToComplete(txid);
157:         }
158: 
159:         // Handle case where txid is already in the process of being validated from a previous call
160:         if (this.cachedValidations[txid].waiting) {
161:             await this.waitForCurrentValidationProcessing(txid);
162:             if (typeof this.cachedValidations[txid].validity === "boolean") {
163:                 return this.cachedValidations[txid].validity!;
164:             }
165:         }
166: 
167:         this.cachedValidations[txid].waiting = true;
168: 
169:         // Check SLP message validity
170:         const txn: Bitcore.Transaction = new Bitcore.Transaction(this.cachedRawTransactions[txid]);
171:         let slpmsg: SlpTransactionDetails;
172:         try {
173:             // @ts-ignore
174:             slpmsg = this.cachedValidations[txid].details = this.slp.parseSlpOutputScript(txn.outputs[0]._scriptBuffer);
175:             if (slpmsg.transactionType === SlpTransactionType.GENESIS) {
176:                 slpmsg.tokenIdHex = txid;
177:             }
178:         } catch (e) {
179:             this.cachedValidations[txid].validity = false;
180:             this.cachedValidations[txid].waiting = false;
181:             this.cachedValidations[txid].invalidReason = "SLP OP_RETURN parsing error (" + e.message + ").";
182:             return this.cachedValidations[txid].validity!;
183:         }
184: 
185:         // Check for tokenId filter
186:         if (tokenIdFilter && slpmsg.tokenIdHex !== tokenIdFilter) {
187:             this.cachedValidations[txid].waiting = false;
188:             this.cachedValidations[txid].invalidReason = "Validator was run with filter only considering tokenId " + tokenIdFilter + " as valid.";
189:             return false; // Don't save boolean result to cache incase cache is ever used without tokenIdFilter.
190:         } else {
191:             if (this.cachedValidations[txid].validity !== false) {
192:                 this.cachedValidations[txid].invalidReason = null;
193:             }
194:         }
195: 
196:         // Check specified token type is being respected
197:         if (tokenTypeFilter && slpmsg.versionType !== tokenTypeFilter) {
198:             this.cachedValidations[txid].validity = null;
199:             this.cachedValidations[txid].waiting = false;
200:             this.cachedValidations[txid].invalidReason = "Validator was run with filter only considering token type: " + tokenTypeFilter + " as valid.";
201:             return false; // Don't save boolean result to cache incase cache is ever used with different token type.
202:         } else {
203:             if (this.cachedValidations[txid].validity !== false) {
204:                 this.cachedValidations[txid].invalidReason = null;
205:             }
206:         }
207: 
208:         // Check DAG validity
209:         if (slpmsg.transactionType === SlpTransactionType.GENESIS) {
210:             // Check for NFT1 child (type 0x41)
211:             if (slpmsg.versionType === 0x41) {
212:                 // An NFT1 parent should be provided at input index 0,
213:                 // so we check this first before checking the whole parent DAG
214:                 let input_txid = txn.inputs[0].prevTxId.toString("hex");
215:                 let input_txhex = await this.retrieveRawTransaction(input_txid);
216:                 let input_tx: Bitcore.Transaction = new Bitcore.Transaction(input_txhex);
217:                 let input_slpmsg;
218:                 try {
219:                     input_slpmsg = this.slp.parseSlpOutputScript(input_tx.outputs[0]._scriptBuffer);
220:                 } catch (_) { }
221:                 if (!input_slpmsg || input_slpmsg.versionType !== 0x81) {
222:                     this.cachedValidations[txid].validity = false;
223:                     this.cachedValidations[txid].waiting = false;
224:                     this.cachedValidations[txid].invalidReason = "NFT1 child GENESIS does not have a valid NFT1 parent input.";
225:                     return this.cachedValidations[txid].validity!;
226:                 }
227:                 // Check that the there is a burned output >0 in the parent txn SLP message
228:                 if (input_slpmsg.transactionType === SlpTransactionType.SEND &&
229:                     (!input_slpmsg.sendOutputs![1].isGreaterThan(0)))
230:                 {
231:                     this.cachedValidations[txid].validity = false;
232:                     this.cachedValidations[txid].waiting = false;
233:                     this.cachedValidations[txid].invalidReason = "NFT1 child's parent has SLP output that is not greater than zero.";
234:                     return this.cachedValidations[txid].validity!;
235:                 } else if ((input_slpmsg.transactionType === SlpTransactionType.GENESIS ||
236:                             input_slpmsg.transactionType === SlpTransactionType.MINT) &&
237:                             !input_slpmsg.genesisOrMintQuantity!.isGreaterThan(0))
238:                 {
239:                     this.cachedValidations[txid].validity = false;
240:                     this.cachedValidations[txid].waiting = false;
241:                     this.cachedValidations[txid].invalidReason = "NFT1 child's parent has SLP output that is not greater than zero.";
242:                     return this.cachedValidations[txid].validity!;
243:                 }
244:                 // Continue to check the NFT1 parent DAG
245:                 let nft_parent_dag_validity = await this.isValidSlpTxid(input_txid, undefined, 0x81);
246:                 this.cachedValidations[txid].validity = nft_parent_dag_validity;
247:                 this.cachedValidations[txid].waiting = false;
248:                 if (!nft_parent_dag_validity) {
249:                     this.cachedValidations[txid].invalidReason = "NFT1 child GENESIS does not have valid parent DAG.";
250:                 }
251:                 return this.cachedValidations[txid].validity!;
252:             }
253:             // All other supported token types (includes 0x01 and 0x81)
254:             // No need to check type here since op_return parser throws on other types.
255:             else {
256:                 this.cachedValidations[txid].validity = true;
257:                 this.cachedValidations[txid].waiting = false;
258:                 return this.cachedValidations[txid].validity!;
259:             }
260:         }
261:         else if (slpmsg.transactionType === SlpTransactionType.MINT) {
262:             for (let i = 0; i < txn.inputs.length; i++) {
263:                 let input_txid = txn.inputs[i].prevTxId.toString("hex");
264:                 let input_txhex = await this.retrieveRawTransaction(input_txid);
265:                 let input_tx: Bitcore.Transaction = new Bitcore.Transaction(input_txhex);
266:                 try {
267:                     let input_slpmsg = this.slp.parseSlpOutputScript(input_tx.outputs[0]._scriptBuffer);
268:                     if (input_slpmsg.transactionType === SlpTransactionType.GENESIS) {
269:                         input_slpmsg.tokenIdHex = input_txid;
270:                     }
271:                     if (input_slpmsg.tokenIdHex === slpmsg.tokenIdHex) {
272:                         if (input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
273:                             if (txn.inputs[i].outputIndex === input_slpmsg.batonVout) {
274:                                 this.cachedValidations[txid].parents.push({
275:                                     txid: txn.inputs[i].prevTxId.toString("hex"),
276:                                     vout: txn.inputs[i].outputIndex!,
277:                                     versionType: input_slpmsg.versionType,
278:                                     valid: null,
279:                                     inputQty: null,
280:                                 });
281:                             }
282:                         }
283:                     }
284:                 } catch (_) {}
285:             }
286:             if (this.cachedValidations[txid].parents.length !== 1) {
287:                 this.cachedValidations[txid].validity = false;
288:                 this.cachedValidations[txid].waiting = false;
289:                 this.cachedValidations[txid].invalidReason = "MINT transaction must have 1 valid baton parent.";
290:                 return this.cachedValidations[txid].validity!;
291:             }
292:         }
293:         else if (slpmsg.transactionType === SlpTransactionType.SEND) {
294:             const tokenOutQty = slpmsg.sendOutputs!.reduce((t, v) => { return t.plus(v); }, new BigNumber(0));
295:             let tokenInQty = new BigNumber(0);
296:             for (let i = 0; i < txn.inputs.length; i++) {
297:                 let input_txid = txn.inputs[i].prevTxId.toString("hex");
298:                 let input_txhex = await this.retrieveRawTransaction(input_txid);
299:                 let input_tx: Bitcore.Transaction = new Bitcore.Transaction(input_txhex);
300:                 try {
301:                     let input_slpmsg = this.slp.parseSlpOutputScript(input_tx.outputs[0]._scriptBuffer);
302:                     if (input_slpmsg.transactionType === SlpTransactionType.GENESIS) {
303:                         input_slpmsg.tokenIdHex = input_txid;
304:                     }
305:                     if (input_slpmsg.tokenIdHex === slpmsg.tokenIdHex) {
306:                         if (input_slpmsg.transactionType === SlpTransactionType.SEND) {
307:                             if (txn.inputs[i].outputIndex! <= input_slpmsg.sendOutputs!.length - 1) {
308:                                 tokenInQty = tokenInQty.plus(input_slpmsg.sendOutputs![txn.inputs[i].outputIndex!]);
309:                                 this.cachedValidations[txid].parents.push({
310:                                     txid: txn.inputs[i].prevTxId.toString("hex"),
311:                                     vout: txn.inputs[i].outputIndex!,
312:                                     versionType: input_slpmsg.versionType,
313:                                     valid: null,
314:                                     inputQty: input_slpmsg.sendOutputs![txn.inputs[i].outputIndex!]
315:                                 });
316:                             }
317:                         }
318:                         else if (input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
319:                             if (txn.inputs[i].outputIndex === 1) {
320:                                 tokenInQty = tokenInQty.plus(input_slpmsg.genesisOrMintQuantity!);
321:                                 this.cachedValidations[txid].parents.push({
322:                                     txid: txn.inputs[i].prevTxId.toString("hex"),
323:                                     vout: txn.inputs[i].outputIndex!,
324:                                     versionType: input_slpmsg.versionType,
325:                                     valid: null,
326:                                     inputQty: input_slpmsg.genesisOrMintQuantity
327:                                 });
328:                             }
329:                         }
330:                     }
331:                 } catch (_) {}
332:             }
333: 
334:             // Check token inputs are greater than token outputs (includes valid and invalid inputs)
335:             if (tokenOutQty.isGreaterThan(tokenInQty)) {
336:                 this.cachedValidations[txid].validity = false;
337:                 this.cachedValidations[txid].waiting = false;
338:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than possible token inputs.";
339:                 return this.cachedValidations[txid].validity!;
340:             }
341:         }
342: 
343:         // Set validity validation-cache for parents, and handle MINT condition with no valid input
344:         // we don't need to check proper token id since we only added parents with same ID in above steps.
345:         const parentTxids = [...new Set(this.cachedValidations[txid].parents.map(p => p.txid))];
346:         for (let i = 0; i < parentTxids.length; i++) {
347:             const valid = await this.isValidSlpTxid(parentTxids[i]);
348:             this.cachedValidations[txid].parents.filter(p => p.txid === parentTxids[i]).map(p => p.valid = valid);
349:             if (this.cachedValidations[txid].details!.transactionType === SlpTransactionType.MINT && !valid) {
350:                 this.cachedValidations[txid].validity = false;
351:                 this.cachedValidations[txid].waiting = false;
352:                 this.cachedValidations[txid].invalidReason = "MINT transaction with invalid baton parent.";
353:                 return this.cachedValidations[txid].validity!;
354:             }
355:         }
356: 
357:         // Check valid inputs are greater than token outputs
358:         if (this.cachedValidations[txid].details!.transactionType === SlpTransactionType.SEND) {
359:             const validInputQty = this.cachedValidations[txid].parents.reduce((t, v) => { return v.valid ? t.plus(v.inputQty!) : t; }, new BigNumber(0));
360:             const tokenOutQty = slpmsg.sendOutputs!.reduce((t, v) => { return t.plus(v); }, new BigNumber(0));
361:             if (tokenOutQty.isGreaterThan(validInputQty)) {
362:                 this.cachedValidations[txid].validity = false;
363:                 this.cachedValidations[txid].waiting = false;
364:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than valid token inputs.";
365:                 return this.cachedValidations[txid].validity!;
366:             }
367:         }
368: 
369:         // Check versionType is not different from valid parents
370:         if (this.cachedValidations[txid].parents.filter(p => p.valid).length > 0) {
371:             const validVersionType = this.cachedValidations[txid].parents.find(p => p.valid!)!.versionType;
372:             if (this.cachedValidations[txid].details!.versionType !== validVersionType) {
373:                 this.cachedValidations[txid].validity = false;
374:                 this.cachedValidations[txid].waiting = false;
375:                 this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid parent.";
376:                 return this.cachedValidations[txid].validity!;
377:             }
378:         }
379:         this.cachedValidations[txid].validity = true;
380:         this.cachedValidations[txid].waiting = false;
381:         return this.cachedValidations[txid].validity!;
382:     }
383: 
384:     async validateSlpTransactions(txids: string[]): Promise<string[]> {
385:         const res = [];
386:         for (let i = 0; i < txids.length; i++) {
387:             res.push((await this.isValidSlpTxid(txids[i])) ? txids[i] : "");
388:         }
389:         return res.filter((id: string) => id.length > 0);
390:     }
391: }"
}

